-- seeder2.sql - LOCAL DEMO DATA ONLY, MySQL 8.4, Flyway V1-V5 required.
-- Select the existing development/test schema in Workbench, then execute this whole file.
-- Empty catalog: inserts exactly the 20 agreed product IDs/SKUs and image URL metadata.
-- Existing catalog: requires those exact 20 IDs/SKUs and never updates any product/image.
-- Five accounts: demo2.admin / demo2.sequence / demo2.mixed / demo2.cold / demo2.wrong
-- Shared LOCAL-ONLY password: DemoCombo@2026 (bcrypt cost 12, current Auth encoder format).
-- Adds synthetic inputs only: 46 customers, 65 COMPLETED orders, 94 order lines.
-- Does NOT insert DATASET_SNAPSHOT, MINING_RUN, PATTERN, COMBO or publication evidence.
-- Matching existing rows are retained; conflicting identities/data abort and roll back.
-- No DELETE/TRUNCATE/UPDATE of application data. No applied migration is changed.
-- Quick start: docs/demo/combo-demo/SEEDER2.md
-- Run with application data backed up/on a test copy; this file must not run in production.
-- Temporary tables and the uniquely named helper routine are removed after success.
-- If execution aborts, application DML is rolled back. See SEEDER2.md for helper cleanup.

DELIMITER $$
CREATE PROCEDURE wspm_seeder2_20261111()
SQL SECURITY INVOKER
BEGIN
    DECLARE old_timezone VARCHAR(64) DEFAULT @@session.time_zone;
    DECLARE lock_name VARCHAR(64);
    DECLARE lock_acquired INT DEFAULT 0;
    DECLARE catalog_was_empty BOOLEAN DEFAULT FALSE;
    DECLARE demo_hash VARCHAR(255) DEFAULT '{bcrypt}$2a$12$.VkgfJiYi/eThuOtO7XtI.4fCCoWDpBJNo0kyhDXbcQrcdaQ5Gdnu';
    DECLARE customer_role VARCHAR(40) DEFAULT '0607f6f6-e469-5029-b3fb-f0dca36fc00f';
    DECLARE admin_role VARCHAR(40) DEFAULT '6a0d16bb-9189-5d9a-a6ea-576d85020457';
    DECLARE stock_warehouse VARCHAR(40) DEFAULT '625e85b8-d3b2-54ae-9cc1-65d13ec0fa35';
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        DROP TEMPORARY TABLE IF EXISTS s2_products,s2_users,s2_customers,s2_orders,s2_items,s2_stock;
        SET SESSION time_zone = old_timezone;
        IF lock_acquired = 1 THEN DO RELEASE_LOCK(lock_name); END IF;
        RESIGNAL;
    END;

    SET lock_name = CONCAT('wspm-seeder2:',LEFT(SHA2(DATABASE(),256),48));
    SELECT GET_LOCK(lock_name,5) INTO lock_acquired;
    IF COALESCE(lock_acquired,0) <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2: another seed is running; retry later.';
    END IF;
    SET SESSION time_zone = '+00:00';
    IF (SELECT COUNT(*) FROM flyway_schema_history WHERE success=1 AND version IN ('1','2','3','4','5')) <> 5 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 requires successful Flyway migrations V1-V5.';
    END IF;

    CREATE TEMPORARY TABLE s2_products(product_id VARCHAR(40) PRIMARY KEY,sku VARCHAR(80) NOT NULL,is_mining BOOLEAN NOT NULL,name VARCHAR(200) NOT NULL,category_id VARCHAR(40) NOT NULL,category_name VARCHAR(160) NOT NULL,price DECIMAL(19,2) NOT NULL,product_status VARCHAR(24) NOT NULL,category_status VARCHAR(24) NOT NULL,image_id VARCHAR(40) NOT NULL,image_url VARCHAR(1024) NULL) DEFAULT CHARSET=utf8mb4;
    CREATE TEMPORARY TABLE s2_users(user_id VARCHAR(40) PRIMARY KEY,username VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL,display_name VARCHAR(160) NOT NULL,is_admin BOOLEAN NOT NULL);
    CREATE TEMPORARY TABLE s2_customers(customer_id VARCHAR(40) PRIMARY KEY,user_id VARCHAR(40) NULL,anonymous_code VARCHAR(80) NOT NULL);
    CREATE TEMPORARY TABLE s2_orders(order_id VARCHAR(40) PRIMARY KEY,customer_id VARCHAR(40) NOT NULL,ordered_at DATETIME(6) NOT NULL,total DECIMAL(19,2) NOT NULL);
    CREATE TEMPORARY TABLE s2_items(order_id VARCHAR(40) NOT NULL,product_id VARCHAR(40) NOT NULL,quantity INT UNSIGNED NOT NULL,list_unit_price DECIMAL(19,2) NOT NULL,sku_snapshot VARCHAR(80) NOT NULL,product_name_snapshot VARCHAR(200) NOT NULL,line_total DECIMAL(19,2) NOT NULL,PRIMARY KEY(order_id,product_id));
    CREATE TEMPORARY TABLE s2_stock(product_id VARCHAR(40) PRIMARY KEY,available_quantity INT UNSIGNED NOT NULL);


    START TRANSACTION;
    -- A fresh schema gets the SAME catalog; partial/different catalogs are rejected.
    SET catalog_was_empty = (SELECT COUNT(*) FROM PRODUCT)=0;
    IF (SELECT COUNT(*) FROM PRODUCT) NOT IN (0,20) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 refuses partial catalogs; expected zero or the agreed 20 products.';
    END IF;
    IF catalog_was_empty THEN
        SELECT DISTINCT e.category_id,e.category_name,CONCAT('seeder2-',e.category_id),e.category_status FROM s2_products e
        WHERE NOT EXISTS(SELECT 1 FROM CATEGORY c WHERE c.category_id=e.category_id);
        SELECT e.product_id,e.sku,e.name,CONCAT('seeder2-',e.product_id),e.category_id,e.price,e.product_status FROM s2_products e;
        SELECT e.image_id,e.product_id,e.image_url,e.name,0 FROM s2_products e WHERE e.image_url IS NOT NULL;
    END IF;
    IF (SELECT COUNT(*) FROM PRODUCT) <> 20 OR
       (SELECT COUNT(*) FROM PRODUCT p JOIN s2_products e ON BINARY p.product_id=BINARY e.product_id AND BINARY p.sku=BINARY e.sku) <> 20 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 requires exactly the 20 existing catalog IDs/SKUs.';
    END IF;
    IF (SELECT COUNT(*) FROM s2_products e JOIN PRODUCT p ON p.product_id=e.product_id JOIN CATEGORY c ON c.category_id=p.category_id WHERE e.is_mining=1 AND BINARY p.status=BINARY 'ACTIVE' AND BINARY c.status=BINARY 'ACTIVE') <> 7 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 requires the seven mining products/categories to be ACTIVE.';
    END IF;
    IF EXISTS(SELECT 1 FROM USER_ACCOUNT u JOIN s2_users e ON u.user_id=e.user_id OR u.username=e.username OR u.email=e.email
        WHERE BINARY u.user_id<>BINARY e.user_id OR NOT(BINARY u.username<=>BINARY e.username) OR NOT(BINARY u.email<=>BINARY e.email) OR BINARY u.password_hash<>BINARY demo_hash OR BINARY u.status<>BINARY 'ACTIVE') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 account collision/changed password; no account was overwritten.';
    END IF;
    IF EXISTS(SELECT 1 FROM CUSTOMER c JOIN s2_customers e ON c.customer_id=e.customer_id OR c.anonymous_code=e.anonymous_code OR (e.user_id IS NOT NULL AND c.user_id=e.user_id)
        WHERE BINARY c.customer_id<>BINARY e.customer_id OR NOT(BINARY c.user_id<=>BINARY e.user_id) OR BINARY c.anonymous_code<>BINARY e.anonymous_code) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 customer collision; no customer was overwritten.';
    END IF;
    IF EXISTS(SELECT 1 FROM ORDERS o JOIN s2_orders e ON o.order_id=e.order_id OR o.order_number=e.order_id
        WHERE BINARY o.order_id<>BINARY e.order_id OR BINARY o.order_number<>BINARY e.order_id OR o.customer_id<>e.customer_id OR o.ordered_at<>e.ordered_at OR NOT(o.completed_at<=>e.ordered_at) OR BINARY o.status<>BINARY 'COMPLETED' OR BINARY o.source<>BINARY 'SYNTHETIC_SEEDER2' OR BINARY o.currency_code<>BINARY 'VND' OR o.list_subtotal<>e.total OR o.grand_total<>e.total OR o.combo_discount_total<>0 OR o.other_discount_total<>0 OR o.shipping_fee<>0 OR o.tax_total<>0 OR o.checkout_id IS NOT NULL) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 order collision/changed order; no order was overwritten.';
    END IF;
    IF EXISTS(SELECT 1 FROM ORDER_ITEM i JOIN s2_orders o ON o.order_id=i.order_id LEFT JOIN s2_items e ON e.order_id=i.order_id AND e.product_id=i.product_id
        WHERE e.product_id IS NULL OR i.quantity<>e.quantity OR i.list_unit_price<>e.list_unit_price OR i.line_total<>e.line_total OR i.allocated_discount_amount<>0 OR BINARY i.sku_snapshot<>BINARY e.sku_snapshot OR BINARY i.product_name_snapshot<>BINARY e.product_name_snapshot OR i.order_applied_combo_id IS NOT NULL) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 order lines conflict; no line was overwritten.';
    END IF;
    IF EXISTS(SELECT 1 FROM ORDER_ITEM i JOIN s2_orders o ON o.order_id=i.order_id GROUP BY i.order_id,i.product_id HAVING COUNT(*)>1) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 duplicate order lines; no line was overwritten.';
    END IF;
    IF EXISTS(SELECT 1 FROM WAREHOUSE WHERE (warehouse_id=stock_warehouse OR code='SYNTHETIC-SEEDER2') AND (BINARY warehouse_id<>BINARY stock_warehouse OR BINARY code<>BINARY 'SYNTHETIC-SEEDER2' OR BINARY status<>BINARY 'ACTIVE')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 warehouse identity/status conflict.';
    END IF;
    IF EXISTS(SELECT 1 FROM INVENTORY_BALANCE b LEFT JOIN s2_stock e ON e.product_id=b.product_id WHERE b.warehouse_id=stock_warehouse AND (e.product_id IS NULL OR b.on_hand_quantity<>e.available_quantity+1 OR b.reserved_quantity<>1)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 synthetic stock was changed; no balance was overwritten.';
    END IF;
    IF EXISTS(SELECT 1 FROM ROLE WHERE (role_id=customer_role AND code<>'CUSTOMER') OR (role_id=admin_role AND code<>'ADMIN') OR (code='CUSTOMER' AND BINARY code<>BINARY 'CUSTOMER') OR (code='ADMIN' AND BINARY code<>BINARY 'ADMIN')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 role identity/case conflict.';
    END IF;
    IF EXISTS(SELECT 1 FROM USER_ROLE ur JOIN s2_users u ON u.user_id=ur.user_id JOIN ROLE r ON r.role_id=ur.role_id WHERE r.code<>'CUSTOMER' AND (u.is_admin=0 OR r.code<>'ADMIN')) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 account has unexpected roles; no roles were removed.';
    END IF;

    SELECT customer_role,'CUSTOMER','Customer' WHERE NOT EXISTS(SELECT 1 FROM ROLE WHERE BINARY code=BINARY 'CUSTOMER');
    SELECT admin_role,'ADMIN','Admin' WHERE NOT EXISTS(SELECT 1 FROM ROLE WHERE BINARY code=BINARY 'ADMIN');
    SELECT role_id INTO customer_role FROM ROLE WHERE BINARY code=BINARY 'CUSTOMER';
    SELECT role_id INTO admin_role FROM ROLE WHERE BINARY code=BINARY 'ADMIN';
    SELECT e.user_id,e.username,e.email,demo_hash,e.display_name,'ACTIVE' FROM s2_users e WHERE NOT EXISTS(SELECT 1 FROM USER_ACCOUNT u WHERE u.user_id=e.user_id);
    SELECT e.user_id,customer_role FROM s2_users e WHERE NOT EXISTS(SELECT 1 FROM USER_ROLE u WHERE u.user_id=e.user_id AND u.role_id=customer_role);
    SELECT e.user_id,admin_role FROM s2_users e WHERE e.is_admin=1 AND NOT EXISTS(SELECT 1 FROM USER_ROLE u WHERE u.user_id=e.user_id AND u.role_id=admin_role);
    SELECT e.customer_id,e.user_id,e.anonymous_code,'SYNTHETIC_SEEDER2' FROM s2_customers e WHERE NOT EXISTS(SELECT 1 FROM CUSTOMER c WHERE c.customer_id=e.customer_id);
    SELECT e.order_id,e.order_id,e.customer_id,e.ordered_at,e.ordered_at,'COMPLETED','SYNTHETIC_SEEDER2','VND',e.total,e.total FROM s2_orders e WHERE NOT EXISTS(SELECT 1 FROM ORDERS o WHERE o.order_id=e.order_id);
    SELECT e.order_id,e.product_id,e.quantity,e.list_unit_price,0,e.line_total,e.sku_snapshot,e.product_name_snapshot FROM s2_items e
    WHERE NOT EXISTS(SELECT 1 FROM ORDER_ITEM i WHERE i.order_id=e.order_id AND i.product_id=e.product_id) ORDER BY e.order_id,e.product_id;
    SELECT stock_warehouse,'SYNTHETIC-SEEDER2','Synthetic Seeder2 Stock','ACTIVE' WHERE NOT EXISTS(SELECT 1 FROM WAREHOUSE WHERE warehouse_id=stock_warehouse);
    SELECT stock_warehouse,e.product_id,e.available_quantity+1,1 FROM s2_stock e
    WHERE NOT EXISTS(SELECT 1 FROM INVENTORY_BALANCE b JOIN WAREHOUSE w ON w.warehouse_id=b.warehouse_id WHERE b.product_id=e.product_id AND BINARY w.status=BINARY 'ACTIVE');

    IF (SELECT COUNT(*) FROM USER_ACCOUNT u JOIN s2_users e ON e.user_id=u.user_id)<>5 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 account readback mismatch; inserts rolled back.';
    END IF;
    IF (SELECT COUNT(*) FROM CUSTOMER c JOIN s2_customers e ON e.customer_id=c.customer_id)<>46 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 customer readback mismatch; inserts rolled back.';
    END IF;
    IF (SELECT COUNT(*) FROM ORDERS o JOIN s2_orders e ON e.order_id=o.order_id)<>65 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 order readback mismatch; inserts rolled back.';
    END IF;
    IF (SELECT COUNT(*) FROM ORDER_ITEM i JOIN s2_orders e ON e.order_id=i.order_id)<>94 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 line readback mismatch; inserts rolled back.';
    END IF;
    IF (SELECT COUNT(*) FROM PRODUCT)<>20 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Seeder2 product count changed; inserts rolled back.';
    END IF;
    DROP TEMPORARY TABLE s2_products,s2_users,s2_customers,s2_orders,s2_items,s2_stock;
    COMMIT;
    SET SESSION time_zone = old_timezone;
    DO RELEASE_LOCK(lock_name);
    SELECT 'READY' AS seeder2_status,20 AS products,5 AS demo_accounts,46 AS demo_customers,65 AS demo_orders,94 AS demo_order_lines;
END$$
DELIMITER ;
CALL wspm_seeder2_20261111();
DROP PROCEDURE wspm_seeder2_20261111;
